 * These are only written when they represent a meaningful step forward from
 * the current DB status; terminal statuses (Landed/Cancelled) are
 * never overwritten by FR24 data.
 *
 * Returns null if no status update is warranted.
 */
function deriveStatusFromFR24(
  pos: { alt: number; gspeed: number; vspeed: number },
  onGround: boolean,
  currentStatus: string | null,
): string | null {
  if (isTerminal(currentStatus)) return null;
  const current = currentStatus?.toLowerCase() ?? '';

  if (!onGround) {
    // Aircraft is airborne — already the most we can say from position data
    if (current !== 'airborne') return 'Airborne';
    return null;
  }

  // Aircraft is on the ground.
  // If it was previously Airborne, it has just landed — mark it immediately
  // rather than waiting for the scraper's next cycle.
  if (current === 'airborne') return 'Landed';

  if (pos.gspeed > 5) {
    // Moving on the ground before departure — taxiing out.
    if (current !== 'taxiing') return 'Taxiing';
    return null;
  }

  // Stationary on the ground and not yet airborne — nothing to update.
  return null;
}

